DO $$ DECLARE def text;BEGIN
SELECT pg_get_functiondef('public.finance_schedule_prepare(uuid,date)'::regprocedure) INTO def;
def:=replace(def,'n:=n+1;END IF;END LOOP;','INSERT INTO fixed_asset_depreciation_schedule(tenant_id,asset_id,period_year,period_month,sequence_no,scheduled_amount) SELECT t,a.id,extract(year FROM ending)::int,extract(month FROM ending)::int,greatest(1,(extract(year FROM age(ending,a.in_service_date))*12+extract(month FROM age(ending,a.in_service_date))+1)::int),amt WHERE NOT EXISTS(SELECT 1 FROM fixed_asset_depreciation_schedule WHERE tenant_id=t AND asset_id=a.id AND period_year=extract(year FROM ending) AND period_month=extract(month FROM ending));n:=n+1;END IF;END LOOP;');
IF def NOT LIKE '%INSERT INTO fixed_asset_depreciation_schedule%' THEN RAISE EXCEPTION 'Depreciation register integration not found';END IF;EXECUTE def;
SELECT pg_get_functiondef('public.finance_schedule_approve(uuid,uuid,date)'::regprocedure) INTO def;def:=replace(def,'IF q.kind=''depreciation'' AND NOT EXISTS','IF q.kind IN(''deferred_expiry'',''package_release'') AND EXISTS(SELECT 1 FROM finance_entry_drafts x WHERE x.tenant_id=t AND x.status=''approved'' AND x.kind=q.kind AND x.source_data->>''item''=q.source_data->>''item'' AND x.entry_date>q.entry_date) THEN RAISE EXCEPTION ''Later deferred releases already approved'';END IF;IF q.kind=''depreciation'' AND NOT EXISTS');EXECUTE def;
END $$;